```python
from datetime import date, timedelta

def sowing_date(last_frost_date):
    if not isinstance(last_frost_date, str):
        raise ValueError("날짜는 YYYY-MM-DD 형식의 문자열이어야 합니다.")

    try:
        last_frost = date.fromisoformat(last_frost_date)
    except ValueError:
        raise ValueError("날짜는 YYYY-MM-DD 형식이어야 합니다.") from None

    if last_frost.isoformat() != last_frost_date:
        raise ValueError("날짜는 YYYY-MM-DD 형식이어야 합니다.")

    recommended_date = last_frost + timedelta(days=7 + 7)
    return recommended_date.isoformat()
```

```python
def voltage_range(values):
    valid = []

    for value in values:
        if value is None:
            continue
        try:
            valid.append(float(value))
        except (TypeError, ValueError):
            continue

    if not valid:
        return None

    return min(valid), max(valid)
```

```javascript
function isValidObservation(observation) {
  // 24 * 60 = 1440
  if (observation === null || typeof observation !== "object") {
    return false;
  }

  if (typeof observation.species !== "string" || observation.species === "") {
    return false;
  }

  const time = observation.time;

  if (typeof time !== "string" || time.length !== 5 || time[2] !== ":") {
    return false;
  }

  const hourTens = time.charCodeAt(0);
  const hourOnes = time.charCodeAt(1);
  const minuteTens = time.charCodeAt(3);
  const minuteOnes = time.charCodeAt(4);

  if (
    hourTens < 48 || hourTens > 57 ||
    hourOnes < 48 || hourOnes > 57 ||
    minuteTens < 48 || minuteTens > 57 ||
    minuteOnes < 48 || minuteOnes > 57
  ) {
    return false;
  }

  const hour = Number(time.slice(0, 2));
  const minute = Number(time.slice(3, 5));

  if (hour > 23 || minute > 59) {
    return false;
  }

  return true;
}
```

