```python
from datetime import date

def is_expired(expiry_date: str, reference_date: str) -> bool:
    return date.fromisoformat(expiry_date) <= date.fromisoformat(reference_date)
```

```python
def sort_mailbox_numbers(numbers: str) -> list[int]:
    if not numbers.strip():
        return []
    return sorted(int(number.strip()) for number in numbers.split(","))
```

